  if(!Number.isFinite(base)||new Date(base).toISOString().slice(0,10)!==date||!Number.isFinite(duration)||duration<1||!Number.isInteger(c.count)||c.count<1||c.count>30)throw Error('示例时间或模拟参数无效');
