 const update=()=>{const ready=!!sessions.length&&!!runSnapshot?.scenario_timeline&&sessions.every(s=>runSnapshot.scenario_timeline.some(t=>t.sample_id===s.id));$('downloadFitBatch').disabled=!ready;for(const id of ['downloadFitOne','downloadTcxOne'])$(id).disabled=!ready;$('downloadFitBatch').textContent=ready?'导出 '+sessions.length+' 个 FIT · ZIP':'FIT 文件集合 · ZIP';$('batchExportInfo').textContent=ready?'每个样本独立保存，附合成来源清单；经纬度取决于本次实验模式。':sessions.length?'该历史实验缺少完整时间轴，无法导出 FIT。':'生成实验后可导出。';};
