 const groupCard=document.createElement('details');groupCard.className='card export-fold';groupCard.id='groupCompareFold';groupCard.innerHTML='<summary>历史实验组对比 · 局部研究</summary><p class="hint">选择两个已有的无GPS合成实验组，比较描述统计。不会修改旧样本。</p><label class="field"><span>组 A</span><select id="compareGroupA"></select></label><label class="field"><span>组 B</span><select id="compareGroupB"></select></label><button id="compareGroups" class="wide">比较两组</button><p id="groupCompareStatus" class="hint" aria-live="polite"></p><div class="scroll"><table><thead><tr><th>组</th><th>样本数</th><th>里程均值 m</th><th>配速 s/km</th><th>RMS m</th></tr></thead><tbody id="groupCompareBody"></tbody></table></div><button id="exportGroupComparison" class="wide" disabled>导出对比 JSON</button>';
